"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate())
const startOfMonth = (d: Date) => new Date(d.getFullYear(), d.getMonth(), 1)
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)
const sameDay = (a?: Date | null, b?: Date | null) => !!a && !!b && +startOfDay(a) === +startOfDay(b)
const sameMonth = (a?: Date | null, b?: Date | null) => !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
/** Monday is 0. */
const weekday = (d: Date) => (d.getDay() + 6) % 7
const two = (n: number) => String(n).padStart(2, "0")

/** Today's date after mount only, so the server and the first client render agree. */
const noop = () => () => {}
const useToday = () => {
  const day = React.useSyncExternalStore(noop, () => startOfDay(new Date()).getTime(), () => null)
  return day === null ? null : new Date(day)
}

type CalendarProps = Omit<React.ComponentProps<"div">, "defaultValue" | "onChange"> & {
  /** The chosen day. */
  value?: Date
  defaultValue?: Date
  onValueChange?: (date: Date) => void
  /** Any date in the month on show. */
  month?: Date
  defaultMonth?: Date
  onMonthChange?: (month: Date) => void
  /** Which day is today. Left out, it's the device's, known once the page has loaded. */
  today?: Date
  /** Days before today can't be chosen. */
  disablePast?: boolean
  locale?: string
}

/**
 * A month of dots: past days filled, today in the accent, the days to come as rings.
 * The day you choose shows its number in italic, because it's yours. Monday first.
 * Arrow keys move by day and week, Page Up and Page Down by month, Home and End to the ends of the week.
 */
function Calendar({
  value: valueProp,
  defaultValue,
  onValueChange,
  month: monthProp,
  defaultMonth,
  onMonthChange,
  today: todayProp,
  disablePast = false,
  locale = "en-GB",
  className,
  ...props
}: CalendarProps) {
  const id = React.useId()
  const clock = useToday()
  const today = todayProp ? startOfDay(todayProp) : clock

  const [innerValue, setInnerValue] = React.useState(defaultValue)
  const value = valueProp ?? innerValue
  const [innerMonth, setInnerMonth] = React.useState(defaultMonth)
  const shown = monthProp ?? innerMonth ?? value ?? today
  const view = shown ? startOfMonth(shown) : null

  const [focus, setFocus] = React.useState<Date>()
  const [turn, setTurn] = React.useState<0 | 1 | -1>(0)
  const [acted, setActed] = React.useState(false)
  const moved = React.useRef(false)
  const grid = React.useRef<HTMLDivElement>(null)

  const goTo = (to: Date, dir: 1 | -1) => {
    if (monthProp === undefined) setInnerMonth(to)
    onMonthChange?.(to)
    setTurn(dir)
  }
  const step = (delta: number) => goTo(new Date(view!.getFullYear(), view!.getMonth() + delta, 1), delta > 0 ? 1 : -1)
  const pick = (date: Date) => {
    if (valueProp === undefined) setInnerValue(date)
    onValueChange?.(date)
    setFocus(date)
    setTurn(0)
    setActed(true)
  }
  const disabled = (date: Date) => disablePast && !!today && date < today

  // The one tab stop: where you were, else the chosen day, else today, else the 1st.
  const stop = view && [focus, value, today].find((d) => d && sameMonth(d, view)) || view

  // After a key moves the stop (perhaps into another month), focus follows it.
  React.useEffect(() => {
    if (!moved.current) return
    moved.current = false
    grid.current?.querySelector<HTMLElement>('[tabindex="0"]')?.focus()
  })

  // The big date over the month: the chosen day, else today, else the 1st. It rolls when it changes.
  const lead = view ? (value && sameMonth(value, view) ? value : today && sameMonth(today, view) ? today : view).getDate() : null
  const target = lead === null ? "" : two(lead)
  const [seen, setSeen] = React.useState(target)
  const [held, setHeld] = React.useState<string | null>(null)
  if (target !== seen) {
    setSeen(target)
    if (seen) setHeld(seen) // keep the old numeral up while it rolls out
  }
  const date = React.useRef<HTMLParagraphElement>(null)
  React.useEffect(() => {
    if (held === null) return
    if (date.current) roll(date.current, () => setHeld(null), "0.4em", turn || (+target > +held ? 1 : -1))
    else setHeld(null)
  }, [held, target, turn])

  const names = new Intl.DateTimeFormat(locale, { weekday: "narrow" })
  const days = new Intl.DateTimeFormat(locale, { weekday: "long" })
  const longDay = new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long" })
  const monday = new Date(2024, 0, 1)
  const titleId = `${id}-title`

  // Weeks as rows of seven; blanks before the 1st and after the last.
  const weeks: (Date | null)[][] = []
  if (view) {
    const last = new Date(view.getFullYear(), view.getMonth() + 1, 0).getDate()
    const cells = [...Array<null>(weekday(view)).fill(null), ...Array.from({ length: last }, (_, i) => addDays(view, i))]
    while (cells.length % 7) cells.push(null)
    for (let i = 0; i < cells.length; i += 7) weeks.push(cells.slice(i, i + 7))
  }
  let wait = 0

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!stop) return
    const to = {
      ArrowLeft: addDays(stop, -1),
      ArrowRight: addDays(stop, 1),
      ArrowUp: addDays(stop, -7),
      ArrowDown: addDays(stop, 7),
      Home: addDays(stop, -weekday(stop)),
      End: addDays(stop, 6 - weekday(stop)),
      PageUp: new Date(stop.getFullYear(), stop.getMonth() - 1, Math.min(stop.getDate(), new Date(stop.getFullYear(), stop.getMonth(), 0).getDate())),
      PageDown: new Date(stop.getFullYear(), stop.getMonth() + 1, Math.min(stop.getDate(), new Date(stop.getFullYear(), stop.getMonth() + 2, 0).getDate())),
    }[e.key]
    if (!to) return
    e.preventDefault()
    moved.current = true
    setFocus(to)
    if (!sameMonth(to, view)) goTo(startOfMonth(to), to > stop ? 1 : -1)
  }

  return (
    <div data-slot="calendar" className={cn("db-month", className)} {...props}>
      <div data-slot="calendar-head" className="db-month-head">
        <p ref={date} className="db-month-date" aria-hidden="true">{held ?? target}</p>
        <p id={titleId} className="db-month-title" aria-live="polite">
          <span className="db-month-name">{view?.toLocaleString(locale, { month: "long" })}</span>
          <span className="db-month-year">{view ? ` ${view.getFullYear()}` : null}</span>
        </p>
        <div className="db-month-nav">
          <button type="button" aria-label="Previous month" disabled={!view} onClick={() => step(-1)}>
            <span aria-hidden="true">←</span>
          </button>
          <button type="button" aria-label="Next month" disabled={!view} onClick={() => step(1)}>
            <span aria-hidden="true">→</span>
          </button>
        </div>
      </div>
      <div
        ref={grid}
        role="grid"
        aria-labelledby={titleId}
        data-slot="calendar-grid"
        data-turn={turn ? "" : undefined}
        data-acted={acted ? "" : undefined}
        style={{ "--from": turn || undefined } as React.CSSProperties}
        className="db-month-grid"
        onKeyDown={onKeyDown}
      >
        <div role="row" className="db-month-week">
          {Array.from({ length: 7 }, (_, i) => {
            const day = addDays(monday, i)
            return (
              <abbr key={i} role="columnheader" title={days.format(day)}>
                {names.format(day)}
              </abbr>
            )
          })}
        </div>
        <React.Fragment key={view ? +view : "unset"}>
          {weeks.map((week, w) => (
            <div key={w} role="row" className="db-month-week">
              {week.map((day, i) => {
                if (!day) return <span key={i} role="gridcell" aria-hidden="true" className="db-month-gap" />
                const when = today ? (day < today ? "past" : sameDay(day, today) ? "today" : "future") : undefined
                const between = !!value && !!today && day > today && day < value
                const off = disabled(day)
                return (
                  <button
                    key={i}
                    type="button"
                    role="gridcell"
                    tabIndex={sameDay(day, stop) ? 0 : -1}
                    aria-selected={sameDay(day, value)}
                    aria-current={when === "today" ? "date" : undefined}
                    aria-disabled={off || undefined}
                    aria-label={longDay.format(day)}
                    data-slot="calendar-day"
                    data-when={when}
                    data-between={between ? "" : undefined}
                    style={{ "--d": day.getDate(), "--k": between ? wait++ : undefined } as React.CSSProperties}
                    className="db-month-day"
                    onClick={() => !off && pick(day)}
                    onFocus={() => setFocus(day)}
                  >
                    {day.getDate()}
                  </button>
                )
              })}
            </div>
          ))}
        </React.Fragment>
      </div>
    </div>
  )
}

export { Calendar, type CalendarProps }

@layer components {
  /* ── db-month ── a month of dots: past filled, today in accent, the rest to come.
     Before the page knows the date (data-when unset) every day is a ring. */
  .db-month { display: grid; gap: var(--db-space-6); max-width: 30rem; }
  .db-month-head { display: grid; grid-template-columns: auto 1fr auto; align-items: last baseline; column-gap: var(--db-space-5); }
  .db-month-date { overflow: clip; min-width: 1.2em; min-height: 0.8em; font-size: var(--db-ff); font-weight: 650; line-height: 0.8; letter-spacing: var(--db-ff-tr); color: var(--db-ink); font-variant-numeric: tabular-nums; }
  .db-month-title { display: grid; line-height: 1.15; }
  .db-month-name { font-size: var(--db-mp); color: var(--db-ink); }
  .db-month-year { font-size: var(--db-mp); color: var(--db-pencil); font-variant-numeric: tabular-nums; }
  .db-month-nav { align-self: center; display: flex; gap: var(--db-space-4); margin-inline-end: -0.2em; } /* the arrows' padding, so the last one meets the grid's edge */
  .db-month-nav > button { appearance: none; border: 0; background: none; padding: 0.2em; color: var(--db-ink); font-size: var(--db-mp); cursor: pointer; transition: translate var(--db-allegro) var(--db-exhale); }
  .db-month-nav > button:is([dir="rtl"], [dir="rtl"] *) > span { display: inline-block; scale: -1 1; } /* an arrow has a direction */
  .db-month-nav > button:first-child:hover { translate: -3px 0; }
  .db-month-nav > button:last-child:hover { translate: 3px 0; }
  .db-month-nav > button:first-child:is([dir="rtl"], [dir="rtl"] *):hover { translate: 3px 0; }
  .db-month-nav > button:last-child:is([dir="rtl"], [dir="rtl"] *):hover { translate: -3px 0; }
  .db-month-nav > button:disabled { color: var(--db-rule-strong); cursor: default; translate: 0 0; }
  .db-month-grid { display: grid; gap: var(--db-space-3); }
  .db-month-week { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--db-space-3); }
  .db-month-week > abbr { text-align: center; text-decoration: none; font-size: var(--db-pp); color: var(--db-pencil); }
  .db-month-day {
    appearance: none; border: 0; margin: 0; padding: 0; aspect-ratio: 1; border-radius: 50%;
    display: grid; place-items: center; cursor: pointer;
    background: transparent; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong); color: transparent;
    font-size: var(--db-p); font-variant-numeric: tabular-nums;
    transition: background-color var(--db-allegro), box-shadow var(--db-allegro), color var(--db-allegro);
  }
  .db-month-day[data-when="past"] { background: var(--db-ink); box-shadow: none; }
  .db-month-day[data-when="today"] { background: var(--db-accent); box-shadow: none; }
  .db-month-day[aria-disabled="true"] { cursor: default; }
  .db-month-day:not([aria-disabled="true"]):is(:hover, :focus-visible) { color: var(--db-paper); }
  .db-month-day:not([data-when="past"], [data-when="today"]):not([aria-disabled="true"]):is(:hover, :focus-visible) { color: var(--db-ink); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-ink); }
  /* The days you're waiting through, between today and the one you chose: half-moons. */
  .db-month-day[data-between] {
    background: linear-gradient(var(--db-ink), var(--db-ink)) no-repeat 0 0 / 50% 100%;
    animation: db-wax var(--db-andante) var(--db-exhale) backwards; animation-delay: calc(var(--k, 0) * var(--db-arpeggio)); /* the moons wax in turn, toward the day you chose */
  }
  .db-month-day[data-between]:is([dir="rtl"], [dir="rtl"] *) { background-position: 100% 0; }
  @keyframes db-wax { from { background-size: 0% 100%; } }
  .db-month-grid[data-turn] .db-month-day { animation: db-turn var(--db-moderato) var(--db-exhale) backwards; animation-delay: calc(var(--d, 0) * 10ms); }
  .db-month-grid[data-turn] .db-month-day[data-between] { animation: db-wax var(--db-andante) var(--db-exhale) backwards; animation-delay: calc(var(--k, 0) * var(--db-arpeggio)); }
  @keyframes db-turn { from { opacity: 0; translate: calc(var(--from, 1) * 8px) 0; } } /* the days sweep in from the side you turned to */
  .db-month-day[data-between]:is(:hover, :focus-visible) { background: transparent; }
  .db-month-day[aria-selected="true"] {
    background: transparent; color: var(--db-ink);
    box-shadow: inset 0 0 0 var(--db-stroke) var(--db-ink);
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-p) * var(--db-expression-scale));
  }
  .db-month-grid[data-acted]:not([data-turn]) .db-month-day[aria-selected="true"] { animation: db-land var(--db-andante) var(--db-spiccato); }
}
